function [data, auxData, metaData, txtData, weights] = mydata_Bembidion_lampros
% file generated by prt_mydata

%% set metaData
metaData.phylum     = 'Arthropoda';
metaData.class      = 'Insecta';
metaData.order      = 'Coleoptera';
metaData.family     = 'Carabidae';
metaData.species    = 'Bembidion_lampros';
metaData.species_en = 'Ground beetle';

metaData.ecoCode.climate = {'Cfb'};
metaData.ecoCode.ecozone = {'THp'};
metaData.ecoCode.habitat = {'0iTg'};
metaData.ecoCode.embryo  = {'Tt'};
metaData.ecoCode.migrate = {'TT'};
metaData.ecoCode.food    = {'biCi'};
metaData.ecoCode.gender  = {'D'};
metaData.ecoCode.reprod  = {'O'};

metaData.T_typical  = C2K(20); % K, body temp
metaData.data_0     = {'ab','t1','t2','t3','am','L1','L2','L3','Li','Le','Ri', 'V0', 'WwL', 'Wwi', 'Ww0'};
metaData.data_1     = {'T_tj', 'T_ab', 'T_te', 't_Ri'};

metaData.COMPLETE   = 2.5;

metaData.author     = {'David Schneider','Andre Gergs'};
metaData.date_subm  = [2025 7 29];
metaData.email      = {'david.schneider1@bayer.com','andre.gergs@bayer.com'};
metaData.address    = {'Bayer AG'};

metaData.curator    = {'Bas Kooijman'};
metaData.email_cur  = {'salm.kooijman@gmail.com'};
metaData.date_acc   = [2025 8 11];

%% set zero-variate data
data.ab = 10; units.ab = 'd'; label.ab = 'age at birth'; bibkey.ab = 'Boye1990';
  temp.ab = C2K(20); units.temp.ab = 'K'; label.temp.ab = 'temperature';
data.t1 = 6; units.t1 = 'd'; label.t1 = 'time since birth at 1st instar'; bibkey.t1 = 'Boye1990';
  temp.t1 = C2K(20); units.temp.t1 = 'K'; label.temp.t1 = 'temperature';
data.t2 = 13; units.t2 = 'd'; label.t2 = 'time since 1st instar at 2nd instar'; bibkey.t2 = 'Boye1990';
  temp.t2 = C2K(20); units.temp.t2 = 'K'; label.temp.t2 = 'temperature';
data.t3 = 20; units.t3 = 'd'; label.t3 = 'time since 2nd instar at 3rd instar'; bibkey.t3 = 'Boye1990';
  temp.t3 = C2K(20); units.temp.t3 = 'K'; label.temp.t3 = 'temperature';
data.am = 365; units.am = 'd'; label.am = 'life span'; bibkey.am = 'Mitc1963';
  temp.am = C2K(20); units.temp.am = 'K'; label.temp.am = 'temperature';
data.Ri = 10; units.Ri = 'eggs'; label.Ri = 'Cumulative number of eggs per female'; bibkey.Ri = 'Pete1998'; 
temp.Ri = C2K(18); units.temp.Ri = 'K'; label.temp.Ri = 'temperature';

data.V0 = 3.96e-5; units.V0 = 'cm^3'; label.V0 = 'egg volume'; bibkey.V0 = 'Mitc1963';
data.L1 = 0.2; units.L1 = 'cm'; label.L1 = 'length at 1st instar'; bibkey.L1 = 'Mitc1963';
data.L2 = 0.296; units.L2 = 'cm'; label.L2 = 'length at 2nd instar'; bibkey.L2 = 'Mitc1963';
data.L3 = 0.45; units.L3 = 'cm'; label.L3 = 'length at 3rd instar'; bibkey.L3 = 'Mitc1963';
data.Li = 0.45; units.Li = 'cm'; label.Li = 'length at imago'; bibkey.Li = 'MarxHomm2021';
%data.Le = 0.3; units.Le = 'cm'; label.Le = 'length at pupa'; bibkey.Le = 'MarxHomm2021';

data.Wwi = 2.73; units.Wwi = 'mg'; label.Wwi = 'mean wet weight of females'; bibkey.Wwi = 'Pete1998';
data.Ww0 = 0.0516; units.Ww0 = 'mg'; label.Ww0 = 'wet weight egg '; bibkey.Ww0 = 'Pete1998';

data.WwL = 1.8; units.WwL = 'mg'; label.WwL = 'wet weight at 3rd instar larva'; bibkey.WwL = 'guess';
%data.WwP = 2.0; units.WwP = 'mg'; label.WwP = 'wet weight at pupa'; bibkey.WwP = 'guess';

%% uni-variate data
% larva to adult development duration
T_tj = [17; 19; 22; 25; 30];
data.T_tj = [T_tj, [41.4; 35.0; 30.4; 24.1; 20.9]];
units.T_tj = {'C', 'd'}; 
label.T_tj = {'temperature', 'larva to adult development duration'};
temp.T_tj = T_tj; units.temp.T_tj = 'K'; label.temp.T_tj = 'temperature';
bibkey.T_tj = 'Boye1990'; 

% egg development duration
T_ab = [12; 17; 19; 22; 25; 30];
data.T_ab = [T_ab, [25.3; 15.0; 10.3; 7.7; 5.6; 4.5]];
units.T_ab = {'C', 'd'}; 
label.T_ab = {'temperature', 'egg development duration'};
temp.T_ab = T_ab; units.temp.T_ab = 'K'; label.temp.T_ab = 'temperature';
bibkey.T_ab = 'Boye1990';

% pupal development duration
T_te = [17; 19; 22; 25; 30]; 
data.T_te = [T_te, [11.2; 9.9; 8.3; 6.1; 5.1]];
units.T_te = {'C', 'd'}; 
label.T_te = {'temperature', 'pupal development duration'};
temp.T_te = T_te; units.temp.T_te = 'K'; label.temp.T_te = 'temperature';
bibkey.T_te = 'Boye1990';

% Cumulative reproduction (eggs) vs time
data.t_Ri = [ ...
    2.06    0.015;
    7.20    0.22;
    12.35   0.81;
    17.49   1.87;
    22.63   3.31;
    27.78   4.73;
    32.92   6.11;
    38.07   7.33;
    43.21   8.45;
    48.35   9.41;
    53.50   10.18;
    58.64   10.81;
    63.79   11.29];
units.t_Ri = {'d', '#'};
label.t_Ri = {'Time since first reproduction', 'Cumulative eggs laid'};
bibkey.t_Ri = 'Pete1998';

%% set weights for all real data
weights = setweights(data, []);
weights.t_Ri = 20 * weights.t_Ri; 
%weights.Wwi = 5* weights.Wwi;
%weights.WwP = 10* weights.WwP;
weights.T_tj = 10 * weights.T_tj;
weights.T_ab = 10 * weights.T_ab;
weights.T_te = 10 * weights.T_te;
%weights.Li= 5 * weights.Li;
%weights.Le= 5 * weights.Le;

%% set pseudodata and respective weights
[data, units, label, weights] = addpseudodata(data, units, label, weights);

%% pack auxData and txtData for output
auxData.temp = temp;
txtData.units = units;
txtData.label = label;
txtData.bibkey = bibkey;

%% Discussion points
% D1 = 'Gompertz and Weibull aging during reproduction phase leading to the observed decline in fecundity. (Pete1998)';
% D2 = 'Egg development was assessed from field-collected females, dissected at different time points after overwintering (Pete1998)';  
% D3 = 'L_T set to zero: Surface-area-specific maintenance costs are neglected, as typical for small insects.';
% D4 = 'Fecundity data were obtained from laboratory experiments under controlled temperature regimes (Pete1998).';
% D5 = 'Larval shape coefficient (del_M_L ≈ 0.22) was derived from estimated wet weight (1.8 mg) and observed length (0.45 cm), ensuring consistency with DEB theory. For context, larvae of Coccinella septempunctata (del_M = 0.0848) and Chrysoperla carnea (del_M = 0.1107) are more compact and less elongated.'
% D6 = 'The egg volume was calculated from actual egg shape (cylinder with hemispherical ends) using measured dimensions (0.55 mm × 0.34 mm, Mitc1963).';

% metaData.discussion = struct('D1', D1, 'D2', D2, 'D3', D3, 'D4', D4, 'D5', D5, 'D6', D6);

%% Facts
% F1 = 'Low lifetime fecundity: Model targets ~10 eggs per female, consistent with empirical data.';
% metaData.bibkey.F1 = 'Pete1998';
% metaData.facts = struct('F1', F1);

%% Acknowledgment
metaData.acknowledgment = '-';

%% Links
metaData.links.id_CoL = 'LDXX';
metaData.links.id_EoL = '66600178';
metaData.links.id_Wiki = 'Bembidion_lampros';
metaData.links.id_ADW = 'Bembidion_lampros';
metaData.links.id_Taxo = '20394';
metaData.links.id_WoRMS = '146896';

%% References

bibkey = 'Boye1990'; type = 'article'; bib = [ ...
'author = {Boye-Jensen, L.}, ' ...
'year = {1990}, ' ...
'title = {Effect of temperature on the development of the immature stages of \emph{Bembidion lampros} ({C}oleoptera: {C}arabidae)}, ' ...
'journal = {Entomophaga}, ' ...
'volume = {35}, ' ...
'pages = {277-281},' ...
'howpublished = {\url{https://link.springer.com/article/10.1007/BF02374803}}'];
metaData.biblist.(bibkey) = ['''@', type, '{', bibkey, ', ', bib, '}'';'];

bibkey = 'MarxHomm2021'; type = 'misc'; bib = [ ...
'author = {Marx, P. and Hommel, B.}, ' ...
'year = {2021}, ' ...
'title = {Steckbrief N\"{u}tzling: Gew\"{o}hnlicher Ahlenl\"{a}ufer (Bembidion lampros)}, ' ...
'institution = {Julius K\"{u}hn-Institut, Institut f\"{u}r \"{O}kologische Chemie, Pflanzenanalytik und Vorratsschutz}, ' ...
'note = {Online resource, accessed 2025-05-12},' ...
'howpublished = {\url{https://wissen.julius-kuehn.de/mediaPublic/nuetzlingsinfo/SB/Bembidion_lampros_SB.pdf}}'];
metaData.biblist.(bibkey) = ['''@', type, '{', bibkey, ', ', bib, '}'';'];

bibkey = 'Kooy2010'; type = 'Book'; bib = [ ...
'author = {Kooijman, S.A.L.M.}, ' ...
'year = {2010}, ' ...
'title  = {Dynamic Energy Budget theory for metabolic organisation}, ' ...
'publisher = {Cambridge Univ. Press, Cambridge}, ' ...
'pages = {Table 4.2 (page 150), 8.1 (page 300)}, ' ...
'howpublished = {\url{http://www.bio.vu.nl/thb/research/bib/Kooy2010.html}}'];
metaData.biblist.(bibkey) = ['''@', type, '{', bibkey, ', ' bib, '}'';'];

bibkey = 'Mitc1963'; type = 'article'; bib = [ ...
'author = {Mitchell, B.}, ' ...
'year = {1963}, ' ...
'title = {Ecology of two carabid beetles, \emph{Bembidion lampros} ({H}erbst) and \emph{Trechus quadristriatus} ({S}chrank). {I}. {L}ife cycles and feeding behaviour}, ' ...
'journal = {Journal of Animal Ecology}, ' ...
'volume = {32}, ' ...
'number = {2}, ' ...
'pages = {289-299}, ' ...
'publisher = {British Ecological Society}, ' ...
'howpublished = {\url{https://www.jstor.org/stable/2542}}'];
metaData.biblist.(bibkey) = ['''@', type, '{', bibkey, ', ', bib, '}'';'];

bibkey = 'Pete1998'; type = 'article'; bib = [ ...
'author = {Petersen, M. K.}, ' ...
'year = {1998}, ' ...
'title = {Fecundity and juvenile survival of \emph{Bembidion lampros} and \emph{Tachyporus hypnorum}}, ' ...
'journal = {Entomologia Experimentalis et Applicata}, ' ...
'volume = {87}, ' ...
'number = {3}, ' ...
'pages = {301-309}, ' ...
'publisher = {Kluwer Academic Publishers}, ' ...
'doi = {10.1046/j.1570-7458.1998.00335.x}'];
metaData.biblist.(bibkey) = ['''@', type, '{', bibkey, ', ', bib, '}'';'];

